import "@typespec/http";
import "@typespec/openapi";
import "./common.tsp";
import "./products.tsp";
import "./skus.tsp";

using Http;

/**
 * EC 受注管理システムの管理画面（Next.js）が呼ぶ JSON API。
 *
 * 認証は Rails の管理画面と同じ Devise のセッション cookie を使う。先に `/auth/sign_in` でログインしておくこと。
 * 書き込み系のリクエストは `Content-Type: application/json` で送る。
 */
@service(#{ title: "EC 受注管理 API" })
@info(#{ version: "1.0.0" })
@server("/", "このサーバー（同一オリジン）")
@useAuth(SessionCookieAuth)
namespace ShopApi;

model SessionCookieAuth is ApiKeyAuth<ApiKeyLocation.cookie, "_rails8_todo_session">;

import "@typespec/http";

using Http;

namespace ShopApi.V1;

/** ページ分割の情報。 */
model Pagination {
  /** 現在のページ（1 始まり）。 */
  page: int32;

  /** 1 ページの件数。 */
  per_page: int32;

  /** 全体の件数。 */
  count: int32;

  /** 全体のページ数。 */
  pages: int32;
}

/** ログインしていない。 */
@error
model UnauthorizedError {
  @statusCode _: 401;
  error: string;
}

/** 対象のリソースがない。 */
@error
model NotFoundError {
  @statusCode _: 404;
  error: string;
}

/** `Content-Type: application/json` 以外で送った。 */
@error
model UnsupportedMediaTypeError {
  @statusCode _: 415;
  error: string;
}

/**
 * 入力が正しくない。`errors` は項目ごとのエラーメッセージで、ネストした項目と配列の要素は
 * object でたどる（例：`{"skus": {"0": {"code": ["を入力してください"]}}}`）。
 */
@error
model ValidationError {
  @statusCode _: 422;
  errors: Record<unknown>;
}

/** 削除に成功した。 */
model NoContentResponse {
  @statusCode _: 204;
}

import "@typespec/http";
import "./common.tsp";
import "./skus.tsp";

using Http;

namespace ShopApi.V1.Products;

/** 販売状態。`draft`：下書き、`on_sale`：販売中、`discontinued`：販売終了。 */
enum Status {
  draft,
  on_sale,
  discontinued,
}

/** 消費税率。`standard`：標準税率 10%、`reduced`：軽減税率 8%（飲食料品）。 */
enum TaxRate {
  standard,
  reduced,
}

/** 商品。サイズや色の違いは SKU として持つ。 */
model Product {
  id: int64;

  /** 商品名。 */
  name: string;

  /** 商品説明。 */
  description: string | null;

  status: Status;
  tax_rate: TaxRate;

  /** SKU（id 順）。 */
  skus: Skus.Sku[];

  created_at: utcDateTime;
  updated_at: utcDateTime;
}

/** 商品の一覧。 */
model ListResponse {
  products: Product[];
  pagination: Pagination;
}

/** 商品の登録。SKU も同時に登録できる。 */
model CreateRequest {
  /** 商品名。 */
  @minLength(1)
  @maxLength(100)
  name: string;

  /** 商品説明。 */
  @maxLength(2000)
  description?: string | null;

  /** 省略すると `draft`。 */
  status?: Status;

  /** 省略すると `standard`。 */
  tax_rate?: TaxRate;

  /** 同時に登録する SKU。コードと、サイズと色の組み合わせは重複できない。 */
  @maxItems(50)
  skus?: Skus.CreateRequest[];
}

/** 商品の更新。送った項目だけを変える。 */
model UpdateRequest {
  /** 商品名。 */
  @minLength(1)
  @maxLength(100)
  name?: string;

  /** 商品説明。`null` で消す。 */
  @maxLength(2000)
  description?: string | null;

  status?: Status;
  tax_rate?: TaxRate;
}

@route("/api/v1/products")
@tag("商品")
interface Products {
  /** 商品の一覧を id の降順で返す。 */
  @get
  @summary("商品の一覧")
  list(
    /** 商品名の部分一致。 */
    @query q?: string,

    /** 販売状態（複数指定できる）。 */
    @query(#{ name: "status[]", explode: true }) status?: Status[],

    /** ページ（1 始まり）。 */
    @query @minValue(1) page?: int32 = 1,

    /** 1 ページの件数。 */
    @query @minValue(1) @maxValue(100) per_page?: int32 = 30,
  ): ListResponse | UnauthorizedError | ValidationError;

  /** 商品と SKU を返す。 */
  @get
  @summary("商品の詳細")
  read(@path id: int64): Product | UnauthorizedError | NotFoundError;

  /** 商品を登録する。`skus` を送ると SKU も同時に登録し、どれか 1 つでも不正なら何も登録しない。 */
  @post
  @summary("商品の登録")
  create(
    @header contentType: "application/json",
    @body body: CreateRequest,
  ): {
    @statusCode _: 201;
    @body body: Product;
  } | UnauthorizedError | UnsupportedMediaTypeError | ValidationError;

  /** 商品を更新する。SKU は SKU の API で変える。 */
  @patch(#{ implicitOptionality: false })
  @summary("商品の更新")
  update(
    @path id: int64,
    @header contentType: "application/json",
    @body body: UpdateRequest,
  ): Product | UnauthorizedError | NotFoundError | UnsupportedMediaTypeError | ValidationError;

  /** 商品を SKU ごと削除する。 */
  @delete
  @summary("商品の削除")
  delete(@path id: int64): NoContentResponse | UnauthorizedError | NotFoundError;
}

import "@typespec/http";
import "./common.tsp";

using Http;

namespace ShopApi.V1.Skus;

/** SKU（在庫を管理する単位）。商品のサイズと色の組み合わせごとに 1 つ。 */
model Sku {
  id: int64;

  /** SKU コード。大文字の英数字とハイフン。 */
  code: string;

  size: string | null;
  color: string | null;

  /** 税込みの販売価格（円）。 */
  price_yen: int32;

  /** 在庫数。 */
  stock_quantity: int32;
}

/** SKU の登録。商品の登録時に `skus` の要素としても使う。 */
model CreateRequest {
  /** SKU コード。英数字とハイフンで、小文字は大文字に直して保存する。 */
  @minLength(1)
  @maxLength(50)
  @pattern("^[A-Za-z0-9][A-Za-z0-9-]*$")
  code: string;

  /** サイズ。サイズがない商品は省略する。 */
  @maxLength(30)
  size?: string | null;

  /** 色。色がない商品は省略する。 */
  @maxLength(30)
  color?: string | null;

  /** 税込みの販売価格（円）。 */
  @minValue(0)
  @maxValue(10000000)
  price_yen: int32;

  /** 在庫数。省略すると 0。 */
  @minValue(0)
  stock_quantity?: int32;
}

/** SKU の更新。送った項目だけを変える。 */
model UpdateRequest {
  @minLength(1)
  @maxLength(50)
  @pattern("^[A-Za-z0-9][A-Za-z0-9-]*$")
  code?: string;

  @maxLength(30)
  size?: string | null;

  @maxLength(30)
  color?: string | null;

  @minValue(0)
  @maxValue(10000000)
  price_yen?: int32;

  @minValue(0)
  stock_quantity?: int32;
}

@tag("SKU")
interface Skus {
  /** 商品に SKU を追加する。 */
  @post
  @route("/api/v1/products/{product_id}/skus")
  @summary("SKU の追加")
  create(
    @path product_id: int64,
    @header contentType: "application/json",
    @body body: CreateRequest,
  ): {
    @statusCode _: 201;
    @body body: Sku;
  } | UnauthorizedError | NotFoundError | UnsupportedMediaTypeError | ValidationError;

  /** SKU を更新する。 */
  @patch(#{ implicitOptionality: false })
  @route("/api/v1/skus/{id}")
  @summary("SKU の更新")
  update(
    @path id: int64,
    @header contentType: "application/json",
    @body body: UpdateRequest,
  ): Sku | UnauthorizedError | NotFoundError | UnsupportedMediaTypeError | ValidationError;

  /** SKU を削除する。 */
  @delete
  @route("/api/v1/skus/{id}")
  @summary("SKU の削除")
  delete(@path id: int64): NoContentResponse | UnauthorizedError | NotFoundError;
}

